    relatedArticles: ["the-disclosure-record", "the-kaminsky-dns-flaw", "satan-and-the-tool-release-argument", "there-is-no-perfect-code", "php-october-2026-vulnerabilities"], // the Learn articles that teach it (sweep 9C)
    relatedTerms: ["responsible-disclosure", "bug-bounty", "dan-kaminsky", "embargo", "cna", "dmca", "kaminsky-dns-flaw", "cve", "katie-moussouris", "cert", "first", "zero-day"], // its neighbours, the existing ones first (sweep 9C)
    sources: [ // every label says what the page says and when it was read (sweep 9C)
      { label: "CERT/CC (Software Engineering Institute, Carnegie Mellon University), The CERT Guide to Coordinated Vulnerability Disclosure, web edition of report CMU/SEI-2017-SR-022, page 'Coordinated Vulnerability Disclosure is a Process, Not an Event' (read 2026-11-12): the two core questions, what to do with the knowledge and who else needs to know what and when; the roles of finder, reporter, vendor and deployer", href: "https://certcc.github.io/CERT-Guide-to-CVD/tutorials/cvd_is_a_process/" }, // CERT/CC (Software Engineering Institute
      { label: "CERT/CC, The CERT Guide to Coordinated Vulnerability Disclosure, Disclosure Timing (read 2026-11-12): no single right deadline; conference schedules drive timing; reasons to release early and to hold back; all disclosure agreements are contingent, because adversaries and independent finders are not party to them; 'Don't tease'", href: "https://certcc.github.io/CERT-Guide-to-CVD/howto/coordination/disclosure_timing/" }, // CERT/CC
      { label: "CERT/CC, The CERT Guide to Coordinated Vulnerability Disclosure, Coordinator (read 2026-11-12): a coordinator acts as a relay or information broker between stakeholders; national CSIRTs such as CISA, the National Cyber Security Centre, JPCERT/CC and NCSC-NL", href: "https://certcc.github.io/CERT-Guide-to-CVD/topics/roles/coordinator/" }, // CERT/CC
      { label: "CERT/CC, Vulnerability Disclosure Policy (read 2026-11-12): vulnerabilities reported to the CERT/CC are disclosed to the public 45 days after the initial report, regardless of the existence or availability of patches or workarounds; earlier or later in extenuating circumstances; credit to the reporter", href: "https://certcc.github.io/certcc_disclosure_policy/" }, // CERT/CC
      { label: "ISO, catalogue page for ISO/IEC 29147:2018, Information technology, Security techniques, Vulnerability disclosure, edition 2, October 2018, confirmed in 2024 (read 2026-11-12): requirements and recommendations to vendors on receiving vulnerability reports and disclosing remediation information; coordination especially important when several vendors are affected; ISO/IEC 30111 covers handling between receipt and disclosure", href: "https://www.iso.org/standard/72311.html" }, // ISO
      { label: "Google Project Zero, Vulnerability Disclosure Policy (read 2026-11-12): 90 days for a patch after notification; details 30 days after the patch when it arrives in time; a 7-day policy for vulnerabilities exploited in the wild; a grace period of 14 days", href: "https://googleprojectzero.blogspot.com/p/vulnerability-disclosure-policy.html" }, // Google Project Zero
      { label: "Microsoft Security Response Center blog (Katie Moussouris), 'Coordinated Vulnerability Disclosure: Bringing Balance to the Force', July 2010 by its address (read 2026-11-12): argues that the term Responsible Disclosure should be deprecated; CVD keeps private reporting and adds a coordinated public disclosure strategy if attacks begin in the wild", href: "https://msrc.microsoft.com/blog/2010/07/coordinated-vulnerability-disclosure-bringing-balance-to-the-force/" }, // Microsoft Security Response Center blog 
      { label: "FIRST, Guidelines and Practices for Multi-Party Vulnerability Coordination and Disclosure, version 1.1, released spring 2020 (read 2026-11-12): written with the NTIA; the definitions of disclosure, finder, coordinator and of upstream, downstream and peer vendors; publish policies with timelines; a reasonable embargo period absent prior public disclosure; use cases and variants", href: "https://www.first.org/global/sigs/vulnerability-coordination/multiparty/guidelines-v1.1" }, // FIRST
      { label: "CERT/CC, Vulnerability Note VU#800113, Multiple DNS implementations vulnerable to cache poisoning, released 8 July 2008, last revised 14 April 2014 (read 2026-11-12): CVE-2008-1447; vendor records notified from 21 April and 5 May 2008; source port randomization as the fix, about 16 additional bits; thanks to Dan Kaminsky of IOActive and Paul Vixie of ISC, with Daniel J. Bernstein credited for randomized source ports", href: "https://www.kb.cert.org/vuls/id/800113" }, // CERT/CC
      { label: "IETF, RFC 9116, A File Format to Aid in Security Vulnerability Disclosure (E. Foudil, Y. Shafranovich), April 2022 (read 2026-11-12): the security.txt file, its location under the well-known path, and the Contact and Expires fields that must always be present", href: "https://www.rfc-editor.org/rfc/rfc9116" }, // IETF
      { label: "United States Department of Justice, press release 'Department of Justice Announces New Policy for Charging Cases under the Computer Fraud and Abuse Act', 19 May 2022 (read 2026-11-12): good-faith security research should not be charged; its definition", href: "https://www.justice.gov/archives/opa/pr/department-justice-announces-new-policy-charging-cases-under-computer-fraud-and-abuse-act" }, // United States Department of Justice
      { label: "European Commission, Cyber Resilience Act policy page (read 2026-11-12): in force since 10 December 2024; reporting obligations from 11 September 2026; main obligations from 11 December 2027; manufacturers must handle vulnerabilities during the lifecycle of their products", href: "https://digital-strategy.ec.europa.eu/en/policies/cyber-resilience-act" }, // European Commission
    ], // 12 sources, one object per line
