    relatedTerms: ["edns", "dns", "dns-rcode", "dns-header-flags", "dnssec", "ecs", "tsig", "fragmentation", "mtu", "recursive-resolver", "flag-day", "paul-vixie"], // its neighbours, the existing ones first (sweep 9B)
    sources: [ // every label says what the page says and when it was read (sweep 9B)
      { label: "IETF, RFC 6891 (STD 75), Extension Mechanisms for DNS (EDNS(0)) (J. Damas, M. Graff, P. Vixie), April 2013 (read 2026-11-12): section 6: the OPT pseudo-RR, type 41, carries no DNS data and must not be cached, forwarded, or stored in or loaded from master files; only one per message, anywhere in the additional section but before TSIG or SIG(0); the fixed part (NAME 0, TYPE, CLASS as the requestor's UDP payload size, TTL as extended RCODE and flags, RDLEN, RDATA) and the option encoding; unknown options ignored; sections 6.2.6 and 7: middleboxes, FORMERR from servers without EDNS, the minimal response of header, question and OPT even when truncated", href: "https://www.rfc-editor.org/rfc/rfc6891" }, // IETF
      { label: "IETF, RFC 2671, Extension Mechanisms for DNS (EDNS0) (P. Vixie), August 1999 (read 2026-11-12): the first specification of the OPT record", href: "https://www.rfc-editor.org/rfc/rfc2671.txt" }, // IETF
      { label: "IETF, RFC 3225, Indicating Resolver Support of DNSSEC (D. Conrad), December 2001 (read 2026-11-12): the DNSSEC OK (DO) bit, the first bit of the third and fourth bytes of the extended RCODE and flags portion of the OPT meta-RR", href: "https://www.rfc-editor.org/rfc/rfc3225.txt" }, // IETF
      { label: "IANA, Domain Name System (DNS) Parameters, last updated 9 November 2026 (read 2026-11-12): resource record type OPT, value 41, references RFC 3225 and RFC 6891; EDNS header flags DO (bit 0) and CO (bit 1)", href: "https://www.iana.org/assignments/dns-parameters/dns-parameters.xhtml" }, // IANA
      { label: "IETF, RFC 9824, Compact Denial of Existence in DNSSEC, September 2025 (read 2026-11-12): section 5.1: the Compact Answers OK (CO) flag, the second most significant bit of the EDNS flags; EDNS is a hop-by-hop signal", href: "https://www.rfc-editor.org/rfc/rfc9824.txt" }, // IETF
      { label: "IETF, RFC 8945 (STD 93), Secret Key Transaction Authentication for DNS (TSIG), November 2020 (read 2026-11-12): the TSIG record, type 250, the other meta-record of the additional section, which has to come last", href: "https://www.rfc-editor.org/rfc/rfc8945.txt" }, // IETF
      { label: "IETF, RFC 9715, IP Fragmentation Avoidance in DNS over UDP (K. Fujiwara, P. Vixie), January 2025, informational (read 2026-11-12): a recommended maximum DNS over UDP payload size of 1400, smaller values allowed; 1232 derived from the IPv6 minimum MTU of 1280", href: "https://www.rfc-editor.org/rfc/rfc9715.txt" }, // IETF
      { label: "NLnet Labs, Unbound documentation, unbound.conf(5) (read 2026-11-12): edns-buffer-size, default 1232 (the DNS Flag Day 2020 recommendation); setting 512 bypasses even the most stringent path MTU problems but generates excessive TCP fallback", href: "https://unbound.docs.nlnetlabs.nl/en/latest/manpages/unbound.conf.html" }, // NLnet Labs
      { label: "ISC, BIND 9 Manual Pages, version 9.20.30, dig (read 2026-11-12): +bufsize sets the UDP message buffer size advertised using EDNS0, between 0 and 65535", href: "https://bind9.readthedocs.io/en/stable/manpages.html" }, // ISC
      { label: "Wireshark, Display Filter Reference: Domain Name System (read 2026-11-12): the fields dns.resp.type, dns.rr.udp_payload_size, dns.resp.ext_rcode, dns.resp.edns0_version, dns.resp.z.do, dns.opt.code and dns.count.add_rr", href: "https://www.wireshark.org/docs/dfref/d/dns.html" }, // Wireshark
      { label: "The Tcpdump Group, tcpdump(1) manual page (read 2026-11-12): additional record counts printed in square brackets as a number followed by au", href: "https://www.tcpdump.org/manpages/tcpdump.1.html" }, // The Tcpdump Group
      { label: "F5, tmsh reference, ltm profile dns (read 2026-11-12): edns0-client-subnet-insert adds the client subnet option to queries that lack one and removes it from responses to clients that did not send it", href: "https://clouddocs.f5.com/cli/tmsh-reference/latest/modules/ltm/ltm_profile_dns.html" }, // F5
    ], // 12 sources, one object per line
