    relatedArticles: ["ascii-the-128-codes", "character-encoding", "utf-8-and-utf-16-byte-by-byte", "mojibake-and-code-pages", "hidden-and-lookalike-characters", "url-encoding-and-idn", "hex-encoding", "unicode-code-points-and-properties"], // the Learn articles that teach it (11/11/2026, batch 3)
    relatedTerms: ["unicode", "utf-8", "encoding", "code-point", "mojibake", "byte", "bit", "telnet", "base64", "rfc"], // its neighbours, the existing ones first (11/11/2026, batch 3)
    sources: [ // every label says what the page says and when it was read (11/11/2026, batch 3)
      { label: "RFC 20, ASCII format for Network Interchange, Vint Cerf, UCLA, 16 October 1969 (read 2026-11-11): standard 7-bit ASCII in an 8-bit byte whose high-order bit is always 0, copied from USAS X3.4-1968, for HOST-HOST connections; SRI ending lines with a period and UCLA with carriage return; the 8 by 16 code table; communication controls, format effectors and information separators; DEL not strictly a control character; positions not to be used internationally without agreement and the pound sign option at 2/3; collation by binary value", href: "https://www.rfc-editor.org/rfc/rfc20" }, // RFC 20
      { label: "Linux man-pages, ascii(7) (read 2026-11-11): the American Standard Code for Information Interchange, a 7-bit code; many 8-bit codes such as ISO/IEC 8859-1 contain it as their lower half; its international counterpart ISO/IEC 646-IRV; upper and lower case differ by one bit, as do 2 and the double quote; published by USASI in 1968", href: "https://man7.org/linux/man-pages/man7/ascii.7.html" }, // Linux man-pages
      { label: "RFC Editor, info page for RFC 20 (read 2026-11-11): STD 80, Internet Standard", href: "https://www.rfc-editor.org/info/rfc20" }, // RFC Editor
      { label: "Ecma International, ECMA-6, 7-bit coded character set, 6th edition, December 1991 (read 2026-11-11): first edition April 1965; the counterpart of ISO/IEC 646; options and the International Reference Version (IRV)", href: "https://ecma-international.org/publications-and-standards/standards/ecma-6/" }, // Ecma International
      { label: "WHATWG, Encoding Standard, living standard last updated 19 October 2026 (read 2026-11-11): ascii, us-ascii, ansi_x3.4-1968, latin1 and iso-8859-1 are labels for windows-1252; 0x80 decodes to U+20AC; ISO/IEC 646 left 0x80 to 0xFF unmapped and software differs on them", href: "https://encoding.spec.whatwg.org/" }, // WHATWG
      { label: "RFC 3629, STD 63, UTF-8, a transformation format of ISO 10646, F. Yergeau, November 2003 (read 2026-11-11): U+0000 to U+007F correspond to octets 00 to 7F; an octet with a US-ASCII value can only stand for that character; the US-ASCII reference ANSI X3.4-1986", href: "https://www.rfc-editor.org/rfc/rfc3629" }, // RFC 3629
      { label: "RFC 5198, Unicode Format for Network Interchange, J. Klensin and M. Padlipsky, March 2008 (read 2026-11-11): protocols historically ASCII-based in Network Virtual Terminal form; Net-Unicode uses UTF-8, normalization and CRLF line endings", href: "https://www.rfc-editor.org/rfc/rfc5198" }, // RFC 5198
      { label: "RFC 5321, Simple Mail Transfer Protocol, J. Klensin, October 2008 (read 2026-11-11): commands and replies are composed of ASCII characters, each 7-bit character sent in an octet with the high-order bit cleared; header fields always in the US-ASCII repertoire; lines end in CR LF, 0D 0A", href: "https://www.rfc-editor.org/rfc/rfc5321" }, // RFC 5321
      { label: "RFC 9110, HTTP Semantics, June 2022 (read 2026-11-11): field values usually constrained to US-ASCII; historically ISO-8859-1; new fields should limit values to visible US-ASCII, SP and HTAB", href: "https://www.rfc-editor.org/rfc/rfc9110" }, // RFC 9110
      { label: "RFC 5890, Internationalized Domain Names for Applications (IDNA): Definitions and Document Framework, August 2010 (read 2026-11-11): LDH labels of ASCII letters, digits and hyphen, at most 63 octets; A-labels beginning xn-- holding Punycode output", href: "https://www.rfc-editor.org/rfc/rfc5890" }, // RFC 5890
    ], // 10 sources, one object per line
