    // Content sweep 11/11/2026, batch 3C/3D: depth, sources and links rewritten to the minimum level (PLAN-content-sweep-20261111).
    slug: "ping-command",
    headword: "ping",
    kind: "term",
    domains: ["enterprise-networking"],
